Contract AutomatedTellerMachineSystem::printReceipt(): Real {

            precondition:
          self.CardIDValidated = true and self.PasswordValidated = true and self.InputCard.oclIsUndefined() = false

            postcondition:
          result = if self.IsDeposit = true then self.DepositedNumber else 0.0 endif

        }

Contract AutomatedTellerMachineSystem::withdrawCash(quantity:Integer): Boolean {

            precondition:
          ((self.CardIDValidated = true and self.PasswordValidated = true) and self.InputCard.oclIsUndefined() = false) and self.InputCard.Balance >= quantity

            postcondition:
          ((self.InputCard.Balance = self.InputCard.Balance@pre - quantity) and self.IsWithdraw = true) and (self.WithdrawedNumber = quantity and result = true)

        }

Contract AutomatedTellerMachineSystem::printReceipt(): Real {

            precondition:
          self.CardIDValidated = true and self.PasswordValidated = true and self.InputCard.oclIsUndefined() = false

            postcondition:
          result = if self.IsWithdraw = true then self.WithdrawedNumber else (if self.IsDeposit = true then self.DepositedNumber else 0.0 endif) endif

        }

Contract ProcessSaleService::makeNewSale(): Boolean {

            precondition:
          ((self.CurrentCashDesk.oclIsUndefined() = false) and (self.CurrentCashDesk.IsOpened = true)) and ((self.CurrentSale.oclIsUndefined() = true) or (self.CurrentSale.IsComplete = true))

            postcondition:
          let sale: Sale in sale.oclIsNew() and sale.IsComplete = false and sale.IsReadytoPay = false and sale.Time = Now and sale.Amount = 0.0 and sale.BelongedCashDesk = self.CurrentCashDesk and self.CurrentCashDesk.ContainedSales->includes(sale) and Sale.allInstances()->includes(sale) and self.CurrentSale = sale and result = true

        }

Contract ProcessSaleService::makeCashPayment(amount:Real): Boolean {

            precondition:
          self.CurrentSale.oclIsUndefined() = false and self.CurrentSale.IsComplete = false and self.CurrentSale.IsReadytoPay = true and amount >= self.CurrentSale.Amount

            postcondition:
          let payment:CashPayment in payment.oclIsNew() and payment.AmountTendered = amount and payment.Balance = amount - self.CurrentSale.Amount and payment.BelongedSale = self.CurrentSale and self.CurrentSale.AssoicatedPayment = payment and CashPayment.allInstances()->includes(payment) and self.CurrentSale.Belongedstore = self.CurrentSale.BelongedCashDesk.BelongedStore and self.CurrentSale.BelongedCashDesk.BelongedStore.Sales->includes(self.CurrentSale) and self.CurrentSale.Time = Now and self.CurrentSale.IsComplete = true and result = true

        }

Contract LibraryManagementSystemSystem::countDownSuspensionDay() {

            precondition:
          true

            postcondition:
          User.allInstances()->forAll(u : User | (if u.SuspensionDays@pre > 0 then u.SuspensionDays = u.SuspensionDays@pre - 1 else u.SuspensionDays = u.SuspensionDays@pre endif) and (if ((u.BorrowStatus@pre = BorrowStatus::SUSPEND and u.OverDueFee = 0.0) and u.SuspensionDays@pre = 1) then u.BorrowStatus = BorrowStatus::NORMAL else u.BorrowStatus = u.BorrowStatus@pre endif))

        }

Contract EvaluateLoanRequestModule::checkCreditHistory(): CreditHistory {

            precondition:
          self.CurrentLoanRequest.oclIsUndefined() = false and self.CurrentLoanRequest.RequestedCreditHistory.oclIsUndefined() = false

            postcondition:
          result = self.CurrentLoanRequest.RequestedCreditHistory

        }

Contract SubmitLoanRequestModule::calculateScore(): Integer {

            precondition:
          self.CurrentLoanRequest.oclIsUndefined() = false and self.CurrentLoanRequest.RequestedCAHistory.oclIsUndefined() = false and self.CurrentLoanRequest.RequestedCreditHistory.oclIsUndefined() = false

            postcondition:
          self.CurrentLoanRequest.CreditScore = 100 and self.CurrentLoanRequest.Status = LoanRequestStatus::SUBMITTED and result = 100

        }
